        var playerScale = Number(cfg && cfg.PLAYER_HEALTHBAR_SCALE);
        if (!isFinite(playerScale)) playerScale = -1;
        var playerX = Number(cfg && cfg.PLAYER_HEALTHBAR_X_OFFSET);
