                        var hasStateProgress = w.FindChildTraverse ? !!w.FindChildTraverse("state_progressbar") : false;
                        var hasLaggingBar = w.FindChildTraverse ? !!w.FindChildTraverse("unit_healthbar_lagging") : false;
